def transform(grid):
    n = len(grid)
    m = len(grid[0])
    max_row = max((row.count(0) for row in grid), default=0)
    max_col = max((sum(grid[r][c] == 0 for r in range(n)) for c in range(m)), default=0)
    out = [[7] * m for _ in range(n)]

    if max_row > max_col:
        left_nines = sum(row[c] == 9 for row in grid for c in range(min(3, m)))
        right_nines = sum(row[c] == 9 for row in grid for c in range(max(0, m - 3), m))
        source_left = left_nines >= right_nines
        for r, row in enumerate(grid):
            if 0 not in row:
                out[r] = row[:]
                continue
            segment = row[:3] if source_left else row[-3:]
            if source_left:
                out[r][m - 3:] = segment
            else:
                out[r][:3] = segment
    else:
        top_nines = sum(grid[r][c] == 9 for r in range(min(3, n)) for c in range(m))
        bottom_nines = sum(grid[r][c] == 9 for r in range(max(0, n - 3), n) for c in range(m))
        source_top = top_nines >= bottom_nines
        for c in range(m):
            col = [grid[r][c] for r in range(n)]
            if 0 not in col:
                for r in range(n):
                    out[r][c] = col[r]
                continue
            segment = col[:3] if source_top else col[-3:]
            start = n - 3 if source_top else 0
            for i in range(3):
                out[start + i][c] = segment[i]
    return out
